`else // functional // 
specify
$width(posedge CKN &&& (ENABLE_SN == 1'b1), 1.0,0,NOTIFIER);
$width(negedge CKN &&& (ENABLE_SN == 1'b1), 1.0,0,NOTIFIER);
$setuphold(negedge CKN &&& (ENABLE_SN == 1'b1), posedge D, 1.0, 1.0, NOTIFIER);
$setuphold(negedge CKN &&& (ENABLE_SN == 1'b1), negedge D, 1.0, 1.0, NOTIFIER);
$recrem(posedge SN, negedge CKN &&& (ENABLE_NOT_D == 1'b1), 1.0, 1.0, NOTIFIER);
$width(negedge SN,1.0,0,NOTIFIER);
