(negedge CKN => (Q:1'bx)) = (1.0,1.0);
if (CKN==1'b0 && D==1'b0)
(negedge SN *> (Q +: 1'b1))=(1.0, 0);
if (CKN==1'b0 && D==1'b1)
(negedge SN *> (Q +: 1'b1))=(1.0, 0);
if (CKN==1'b1 && D==1'b0)
(negedge SN *> (Q +: 1'b1))=(1.0, 0);
if (CKN==1'b1 && D==1'b1)
(negedge SN *> (Q +: 1'b1))=(1.0, 0);

